[ExtensionOf(classStr(GUPSalesOrderCalculator))]
public final class METGUPSalesOrderCalculator_Extension
{
    private METGUPOrderAttributeValueTmp orderAttributeValueHeader, orderAttributeValueLine;

}

Method.Source:
    protected void initializeDataAcessor()
    {
        next initializeDataAcessor();
        METGUPRetailPricingDataManager metDataManager = new METGUPRetailPricingDataManager(currentChannel.RecId, this.getTransactionId(), tempOrderItem, true);
        metDataManager.parmOrderAttributeValueHeader(orderAttributeValueHeader);
        metDataManager.parmOrderAttributeValueLine(orderAttributeValueLine);

        pricingManager = metDataManager;
    }

    protected void initializeForDataManagerPerformance()
    {
        SalesLine salesLineLocal;
        InventTable inventTable;
        InventDimCombination inventDimCombination;
        RetailTempOrderItem tempOrderItem_MET = this.tempOrderItem;
        UnitOfMeasure unitOfMeasure;

        if (!tmpOrderItemInitialized)
        {
            this.initializeOrderAttributeValue();

            insert_recordset tempOrderItem_MET(itemId, Product, UnitOfMeasure)
            select itemId, Product from inventTable
            join salesLineLocal
                where salesLineLocal.ItemId == inventTable.ItemId
                    && salesLineLocal.SalesId == this.salesId
            outer join RecId from unitOfMeasure
            group by inventTable.ItemId, inventTable.Product, unitOfMeasure.RecId
                where unitOfMeasure.Symbol == salesLineLocal.SalesUnit;
        
            if (currentSalesLine.ItemId)
            {
                select firstOnly RecId from tempOrderItem_MET
                where tempOrderItem_MET.ItemId == currentSalesLine.ItemId;
            
                if (!tempOrderItem_MET)
                {
                    insert_recordset tempOrderItem_MET(itemId, Product, UnitOfMeasure)
                    select itemId, Product from inventTable
                        where inventTable.ItemId == currentSalesLine.ItemId
                    join RecId from unitOfMeasure
                    group by inventTable.ItemId, inventTable.Product, unitOfMeasure.RecId;
                }
            }
        
            tmpOrderItemInitialized = true;
        }

        next initializeForDataManagerPerformance();
    }

    private void initializeOrderAttributeValueHeader()
    {
        SalesTable pricingObject;
        select firstonly pricingObject where pricingObject.SalesId == salesId;

        GUPPricingAttributeLink attrLink;
        GUPPricingAttributeGroup attrGroup;
        while select PriceAttributeClassId, Source, RecId from attrLink
            where attrLink.PriceAttributeClassId != 0
               && attrLink.AttributeProviderClassId == 0
               && (attrLink.Source == GUPPricingAttributeSource::Customer
                || attrLink.Source == GUPPricingAttributeSource::SalesTable)
            exists join attrGroup
            where attrGroup.Name == attrLink.PriceAttributeGroupName
               && attrGroup.IsValid == NoYes::Yes
        {
            orderAttributeValueHeader.Source = attrLink.Source;
            orderAttributeValueHeader.PriceAttributeClassId = attrLink.PriceAttributeClassId;
            orderAttributeValueHeader.AttributeLink = attrLink.RecId;
            orderAttributeValueHeader.AttributeValue = GUPPricingAttributeRepository::priceAttribute(attrLink.PriceAttributeClassId).getValueOfAttribute(pricingObject).ToString();
            orderAttributeValueHeader.insert();
        }
    }

    private void initializeOrderAttributeValueLine()
    {
        GUPPricingAttributeLink attrLink;
        GUPPricingAttributeGroup attrGroup;
        METGUPOrderAttributeValueTmp orderAttributeValueTmp;

        insert_recordset orderAttributeValueTmp(PriceAttributeClassId, Source, AttributeLink)
        select PriceAttributeClassId, Source, RecId from attrLink
            where attrLink.PriceAttributeClassId != 0
               && attrLink.AttributeProviderClassId == 0
               && (attrLink.Source == GUPPricingAttributeSource::Product
                   || attrLink.Source == GUPPricingAttributeSource::SalesLine)
               && !(attrLink.TableName == tableStr(EcoResProductCategory)
                    && attrLink.FieldName == fieldStr(EcoResProductCategory, Category)) // Exclude Category since the attr value is composed by method GUPPricingAttributeEcoResProductCategoryCategory.getValueOfAttribute().
            exists join attrGroup
            where attrGroup.Name == attrLink.PriceAttributeGroupName
               && attrGroup.IsValid == NoYes::Yes;

        SalesLine pricingObject;
        while select pricingObject
            where pricingObject.SalesId == salesId
        {
            this.InsertLinePricingObjectAttributeValue(orderAttributeValueTmp, pricingObject);
        }

        if (this.currentSalesLine.ItemId)
        {
            this.InsertLinePricingObjectAttributeValue(orderAttributeValueTmp, this.currentSalesLine);
        }
    }

    private void InsertLinePricingObjectAttributeValue(METGUPOrderAttributeValueTmp _orderAttributeValueTmp, SalesLine _pricingObject)
    {
        while select _orderAttributeValueTmp
        {
            orderAttributeValueLine.data(_orderAttributeValueTmp.data());
            orderAttributeValueLine.AttributeValue = GUPPricingAttributeRepository::priceAttribute(orderAttributeValueLine.PriceAttributeClassId).getValueOfAttribute(_pricingObject).ToString();

            if (orderAttributeValueLine.AttributeValue != '')
            {
                orderAttributeValueLine.insert();
            }
        }
    }
